import os
import cv2
import numpy as np
from PIL import Image, ImageDraw, ImageFont, ImageFilter
import qrcode

print("=== Generating Back Card Texture for SMKN 1 Beringin / Dika Armadana ===")
# NOTE: Front card is authoritatively generated by render_exact_user_card.py.
# This script exclusively generates public/lanyard/backCard.png and backCard-mobile.webp.

bc_orig_path = r'C:\Users\Hype AMD\.gemini\antigravity\brain\73f32cd5-9018-452e-bf40-e08d27c74f6e\scratch\textures\backCard-BGPpqBds.png'
orig = cv2.imread(bc_orig_path)
if orig is None:
    raise FileNotFoundError(f"Base backCard template not found: {bc_orig_path}")
H, W = orig.shape[:2]

# --- 1. SEAMLESS HEADER CLEANUP (REMOVE OLD PENTAGON LOGO + "SMK TEXMACO SEMARANG") ---
print("Step 1: Removing old logo and text with grid-preserving ShiftMap...")
sub_orig = orig[0:305, 380:1024].copy()
H_s, W_s = sub_orig.shape[:2]

# Exact contour mask of old pentagon emblem (x=440..662, y=52..270 globally)
pent_mask = np.zeros((H_s, W_s), dtype=np.uint8)
roi_pent = sub_orig[52:270, 60:282]
pent_dark = (cv2.cvtColor(roi_pent, cv2.COLOR_BGR2GRAY) < 85).astype(np.uint8)
cnts, _ = cv2.findContours(pent_dark, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
biggest = max(cnts, key=cv2.contourArea)
pm = np.zeros_like(pent_dark, dtype=np.uint8)
cv2.drawContours(pm, [biggest], -1, 255, thickness=cv2.FILLED)
pent_mask[52:270, 60:282] = cv2.dilate(pm, np.ones((7, 7), np.uint8), iterations=1)

# Exact connected-component mask of all 18 letters in "SMK TEXMACO SEMARANG" (x=645..995, y=70..235)
text_mask = np.zeros((H_s, W_s), dtype=np.uint8)
roi_text = sub_orig[70:235, 265:615]
t_dark = (cv2.cvtColor(roi_text, cv2.COLOR_BGR2GRAY) < 95).astype(np.uint8)
num_t, lab_t, stats_t, _ = cv2.connectedComponentsWithStats(t_dark)
tm = np.zeros_like(t_dark, dtype=np.uint8)
for i in range(1, num_t):
    x, y, w, h, area = stats_t[i]
    # Skip components touching top diagonal navy ribbon or bottom right bar
    if y == 0 or (y + h >= 164):
        continue
    if area >= 90:
        tm[lab_t == i] = 255
text_mask[70:235, 265:615] = cv2.dilate(tm, np.ones((9, 9), np.uint8), iterations=1)

# Seamless grid-free vintage cream paper backdrop for isolating ShiftMap sampling away from navy borders
cs = orig[300:900, 6:84].copy()
rb_diff = cs[:, :, 2].astype(np.int16) - cs[:, :, 0].astype(np.int16)
cs_gray = cv2.cvtColor(cs, cv2.COLOR_BGR2GRAY)
grid_in_cs = ((rb_diff < 28) & (cs_gray > 125) & (cs_gray < 218)).astype(np.uint8) * 255
grid_in_cs = cv2.dilate(grid_in_cs, np.ones((3, 3), np.uint8), iterations=1)
cs_nogrid = cv2.inpaint(cs, grid_in_cs, 3, cv2.INPAINT_TELEA)

src_med = np.median(cs_nogrid.reshape(-1, 3), axis=0)
dst_med = np.array([198.0, 224.0, 237.0])
cs_nogrid = np.clip(cs_nogrid.astype(np.float32) + (dst_med - src_med), 0, 255).astype(np.uint8)

rng = np.random.default_rng(11)
tile_w = cs_nogrid.shape[1]
step_w = 56
backdrop_acc = np.zeros((H_s, W_s, 3), dtype=np.float32)
weight_acc = np.zeros((H_s, W_s, 1), dtype=np.float32)
ramp_x = np.ones((1, tile_w, 1), dtype=np.float32)
blend = 18
ramp_x[0, :blend, 0] = np.linspace(0.0, 1.0, blend)
ramp_x[0, -blend:, 0] = np.linspace(1.0, 0.0, blend)

for x0 in range(-18, W_s, step_w):
    y_off = int(rng.integers(0, 600 - H_s))
    piece = cs_nogrid[y_off:y_off + H_s, :].astype(np.float32)
    if rng.random() > 0.5:
        piece = piece[:, ::-1]
    sx = max(0, x0)
    ex = min(W_s, x0 + tile_w)
    px0 = sx - x0
    px1 = ex - x0
    w_p = ramp_x[:, px0:px1, :]
    backdrop_acc[:, sx:ex] += piece[:, px0:px1] * w_p
    weight_acc[:, sx:ex] += w_p
backdrop = np.clip(backdrop_acc / np.maximum(weight_acc, 1e-5), 0, 255).astype(np.uint8)

# Mask out SCAN HERE, diagonal top-right corner, right vertical bar, and main QR box from exemplars
gray_s = cv2.cvtColor(sub_orig, cv2.COLOR_BGR2GRAY)
other_mask = np.zeros((H_s, W_s), dtype=np.uint8)
other_mask[20:260, 0:62] = 255
navy_dark = (gray_s < 110).astype(np.uint8) * 255
n_d, l_d, s_d, _ = cv2.connectedComponentsWithStats(navy_dark)
big_dark = np.zeros_like(navy_dark)
for i in range(1, n_d):
    if s_d[i, cv2.CC_STAT_AREA] > 250:
        big_dark[l_d == i] = 255
other_mask = cv2.bitwise_or(other_mask, cv2.dilate(big_dark, np.ones((15, 15), np.uint8), iterations=1))

sub_erase = cv2.bitwise_or(pent_mask, text_mask)
other_only = cv2.bitwise_and(other_mask, cv2.bitwise_not(sub_erase))

work_buf = sub_orig.copy()
work_buf[other_only > 0] = backdrop[other_only > 0]

# Pass 1: Inpaint old text strokes
work1 = work_buf.copy()
work1[pent_mask > 0] = backdrop[pent_mask > 0]
valid1 = (text_mask == 0).astype(np.uint8) * 255
out1 = work1.copy()
cv2.xphoto.inpaint(work1, valid1, out1, cv2.xphoto.INPAINT_SHIFTMAP)

# Pass 2: Inpaint old pentagon polygon cleanly using filled right-side paper
work2 = work_buf.copy()
work2[text_mask > 0] = out1[text_mask > 0]
valid2 = (pent_mask == 0).astype(np.uint8) * 255
out2 = work2.copy()
cv2.xphoto.inpaint(work2, valid2, out2, cv2.xphoto.INPAINT_SHIFTMAP)

alpha = cv2.GaussianBlur(sub_erase.astype(np.float32) / 255.0, (5, 5), 1.0)
alpha = np.clip(alpha * 1.4, 0.0, 1.0)[:, :, None]
clean_header = (out2.astype(np.float32) * alpha + sub_orig.astype(np.float32) * (1.0 - alpha)).astype(np.uint8)
orig[0:305, 380:1024] = clean_header

# --- 2. PLACE OFFICIAL SMKN 1 BERINGIN LOGO & TYPOGRAPHY ---
print("Step 2: Compositing SMKN 1 Beringin logo and matching geometric typography...")
bc = Image.fromarray(cv2.cvtColor(orig, cv2.COLOR_BGR2RGBA))
bc_draw = ImageDraw.Draw(bc)

logo = Image.open('public/assets/smkn1-beringin-logo.png').convert('RGBA')
lw_bc = 138
lh_bc = int(logo.height * (lw_bc / logo.width))
logo_bc = logo.resize((lw_bc, lh_bc), Image.Resampling.LANCZOS)

lx, ly = 456, 70
shadow_mask = logo_bc.split()[3].filter(ImageFilter.GaussianBlur(3.5))
shadow = Image.new('RGBA', (lw_bc, lh_bc), (12, 20, 32, 55))
shadow.putalpha(shadow_mask)
bc.paste(shadow, (lx + 2, ly + 3), shadow)
bc.paste(logo_bc, (lx, ly), logo_bc)

font_school = ImageFont.truetype('fonts/Plus_Jakarta_Sans_800.ttf', 44)
color_ink = (12, 22, 36, 255)
tx = 612
lines = ['SMK', 'NEGERI 1', 'BERINGIN']
line_step = 44
b0 = font_school.getbbox('SMK')
cap_h = b0[3] - b0[1]
total_h = 2 * line_step + cap_h
start_y = int(round((ly + lh_bc / 2.0) - total_h / 2.0 - b0[1]))
for idx, text_line in enumerate(lines):
    bc_draw.text((tx, start_y + idx * line_step), text_line, fill=color_ink, font=font_school)

# Subtle paper grain distress integration across newly composited logo + school ink
bc_np = np.array(bc, dtype=np.float32)
grain_src = cv2.cvtColor(clean_header, cv2.COLOR_BGR2GRAY).astype(np.float32)
grain_dev = grain_src - cv2.GaussianBlur(grain_src, (11, 11), 0)
h_roi = bc_np[50:240, 445:860, :3]
g_roi = grain_dev[50:240, 65:480]
distress = np.clip((g_roi - 3.0) * 1.4, 0, 26)[:, :, None]
bc_np[50:240, 445:860, :3] = np.clip(h_roi + distress * 0.45, 0, 255)
bc = Image.fromarray(bc_np.astype(np.uint8), mode='RGBA')

# --- 3. OFFICIAL INSTAGRAM @dprxz_ QR CODE ---
print("Step 3: Generating scannable Instagram QR code for @dprxz_...")
target_url = 'https://www.instagram.com/dprxz_/'
qr = qrcode.QRCode(
    version=2,
    error_correction=qrcode.constants.ERROR_CORRECT_M,
    box_size=18,
    border=2,
)
qr.add_data(target_url)
qr.make(fit=True)

C_NAVY = (4, 24, 46, 255)
C_CREAM = (237, 225, 198, 255)
qr_pil = qr.make_image(fill_color=C_CREAM[:3], back_color=C_NAVY[:3]).convert('RGBA')

clean_w, clean_h = 580, 580
clean_x = 504 - clean_w // 2
clean_y = 820 - clean_h // 2

patch_qr = np.zeros((clean_h, clean_w, 4), dtype=np.uint8)
patch_qr[:, :, 0] = C_NAVY[0]
patch_qr[:, :, 1] = C_NAVY[1]
patch_qr[:, :, 2] = C_NAVY[2]
patch_qr[:, :, 3] = 255

rng_qr = np.random.default_rng(42)
noise_qr = rng_qr.normal(0, 1.5, (clean_h, clean_w, 3)).astype(np.int16)
patch_qr[:, :, :3] = np.clip(patch_qr[:, :, :3].astype(np.int16) + noise_qr, 0, 255).astype(np.uint8)
# Feather outer 14px margin of the navy patch so there is zero hard box seam against distressed navy
qr_alpha = np.ones((clean_h, clean_w), dtype=np.float32) * 255.0
for edge in range(14):
    val = int(255.0 * (edge + 1) / 15.0)
    qr_alpha[edge, edge:-edge] = np.minimum(qr_alpha[edge, edge:-edge], val)
    qr_alpha[-edge-1, edge:-edge] = np.minimum(qr_alpha[-edge-1, edge:-edge], val)
    qr_alpha[edge:-edge, edge] = np.minimum(qr_alpha[edge:-edge, edge], val)
    qr_alpha[edge:-edge, -edge-1] = np.minimum(qr_alpha[edge:-edge, -edge-1], val)
patch_qr[:, :, 3] = qr_alpha.astype(np.uint8)

patch_qr_img = Image.fromarray(patch_qr, mode='RGBA')
bc.paste(patch_qr_img, (clean_x, clean_y), patch_qr_img)

qx = 504 - qr_pil.width // 2
qy = 820 - qr_pil.height // 2
bc.paste(qr_pil, (qx, qy))

# --- 4. SEAMLESS DIKA ARMADANA NAME BANNER ---
print("Step 4: Updating bottom banner cleanly to DIKA ARMADANA...")
banner_bgr = cv2.cvtColor(np.array(bc)[1288:1496, 114:945, :3], cv2.COLOR_RGB2BGR)
bh, bw = banner_bgr.shape[:2]
b_gray = cv2.cvtColor(banner_bgr, cv2.COLOR_BGR2GRAY)

# Detect ONLY letters of "MUHAMMAD ALFARI YUSUF" (strictly inside dark navy x=55..768, y=20..96)
name_roi = b_gray[20:96, 55:768]
n_bright = (name_roi > 110).astype(np.uint8)
num_n, lab_n, stats_n, _ = cv2.connectedComponentsWithStats(n_bright)
nm = np.zeros_like(n_bright, dtype=np.uint8)
for i in range(1, num_n):
    x, y, w, h, area = stats_n[i]
    if area >= 10:
        nm[lab_n == i] = 255

name_mask = np.zeros((bh, bw), dtype=np.uint8)
name_mask[20:96, 55:768] = cv2.dilate(nm, np.ones((11, 11), np.uint8), iterations=1)

# Clean distressed navy texture (between name and Junior Developer) without bright crackles/bars
navy_sample = banner_bgr[94:124, 240:600].copy()
ns_gray = cv2.cvtColor(navy_sample, cv2.COLOR_BGR2GRAY)
bright_ns = cv2.dilate((ns_gray > 85).astype(np.uint8) * 255, np.ones((5, 5), np.uint8))
navy_sample = cv2.inpaint(navy_sample, bright_ns, 3, cv2.INPAINT_TELEA)
navy_tile = np.tile(navy_sample, ((bh // navy_sample.shape[0]) + 1, (bw // navy_sample.shape[1]) + 1, 1))[:bh, :bw, :]

b_other = np.zeros((bh, bw), dtype=np.uint8)
# Exclude ALL borders, corner leaf ornament, "Junior Developer", horizontal lines, and right torn edge
b_other[b_gray > 95] = 255
b_other[:16, :] = 255
b_other[100:, :] = 255
b_other[:, :52] = 255
b_other[:, 768:] = 255
b_other = cv2.dilate(b_other, np.ones((11, 11), np.uint8), iterations=1)
b_other_only = cv2.bitwise_and(b_other, cv2.bitwise_not(name_mask))

b_work = banner_bgr.copy()
b_work[b_other_only > 0] = navy_tile[b_other_only > 0]
b_valid = (name_mask == 0).astype(np.uint8) * 255
b_out = b_work.copy()
cv2.xphoto.inpaint(b_work, b_valid, b_out, cv2.xphoto.INPAINT_SHIFTMAP)

b_alpha = cv2.GaussianBlur(name_mask.astype(np.float32) / 255.0, (5, 5), 1.0)
b_alpha = np.clip(b_alpha * 1.4, 0.0, 1.0)[:, :, None]
clean_banner_bgr = (b_out.astype(np.float32) * b_alpha + banner_bgr.astype(np.float32) * (1.0 - b_alpha)).astype(np.uint8)

banner_pil = Image.fromarray(cv2.cvtColor(clean_banner_bgr, cv2.COLOR_BGR2RGBA))
draw_b = ImageDraw.Draw(banner_pil)
font_dika = ImageFont.truetype('fonts/Plus_Jakarta_Sans_800.ttf', 52)
text_dika = 'DIKA ARMADANA'
bbox_d = font_dika.getbbox(text_dika)
tw_d, th_d = bbox_d[2] - bbox_d[0], bbox_d[3] - bbox_d[1]
tx_d = (bw - tw_d) // 2
ty_d = 20 + (66 - th_d) // 2 - bbox_d[1]
draw_b.text((tx_d, ty_d), text_dika, fill=(244, 237, 218, 255), font=font_dika)

bc.paste(banner_pil, (114, 1288))

# --- 5. EXPORT & VERIFY ---
bc_rgb = bc.convert('RGB')
bc_rgb.save('public/lanyard/backCard.png', quality=98)
bc_rgb.save('public/lanyard/backCard-mobile.webp', 'WEBP', quality=95)

inv = 255 - cv2.cvtColor(np.array(bc_rgb), cv2.COLOR_RGB2GRAY)
det = cv2.QRCodeDetector()
val, pts, _ = det.detectAndDecode(inv)
print("QR code verify:", val)
assert val == target_url, f"QR code decode failed: {val}"
print("=== Back Card generated & verified 100%! ===")
